,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ''Collected Today'' AS label,',
'       TO_CHAR(NVL(SUM(PAID_AMOUNT), 0), ''FM999,999,990'') AS value,',
'       ''card-collected'' AS card_class,',
'       ''fa fa-money'' AS icon',
'FROM   HMS_INVOICES',
'WHERE  INVOICE_DATE = TRUNC(SYSDATE)',
'UNION ALL',
'SELECT ''Collected This Month'',',
'       TO_CHAR(NVL(SUM(PAID_AMOUNT), 0), ''FM999,999,990''),',
'       ''card-month'',',
'       ''fa fa-calendar-check-o''',
'FROM   HMS_INVOICES',
'WHERE  TRUNC(INVOICE_DATE, ''MM'') = TRUNC(SYSDATE, ''MM'')',
'UNION ALL',
'SELECT ''Pending Balance'',',
'       TO_CHAR(NVL(SUM(TOTAL_AMOUNT - DISCOUNT - PAID_AMOUNT), 0), ''FM999,999,990''),',
'       ''card-pending'',',
'       ''fa fa-exclamation-circle''',
'FROM   HMS_INVOICES',
'WHERE  STATUS <> ''Paid''',
'UNION ALL',
'SELECT ''Unpaid Invoices'',',
'       TO_CHAR(COUNT(*)),',
'       ''card-unpaid'',',
'       ''fa fa-file-text-o''',
'FROM   HMS_INVOICES',
'WHERE  STATUS <> ''Paid'''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
,p_plug_required_role=>wwv_flow_imp.id(3896706863723731238)
,p_created_on=>wwv_flow_imp.dz('20261015073147Z')
,p_updated_on=>wwv_flow_imp.dz('20261020061647Z')
,p_created_by=>'MUHAMMADHAMMADMATLOOB@GMAIL.COM'
,p_updated_by=>'MUHAMMADHAMMADMATLOOB@GMAIL.COM'
);
