wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(3493757795065774915)
,p_process_sequence=>50
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Generate Invoice'
,p_static_id=>'generate-invoice'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_exists   NUMBER;',
'    l_patient  NUMBER;',
'    l_fee      NUMBER;',
'    l_inv_id   NUMBER;',
'    l_inv_no   VARCHAR2(20);',
'BEGIN',
'    SELECT COUNT(*) INTO l_exists',
'    FROM   HMS_INVOICES',
'    WHERE  VISIT_ID = :P7_VISIT_ID;',
'',
'    IF l_exists > 0 THEN',
'        raise_application_error(-20001, ''Is visit ka invoice pehle se bana hua hai.'');',
'    END IF;',
'',
'    SELECT v.PATIENT_ID, d.CONSULT_FEE',
'    INTO   l_patient, l_fee',
'    FROM   HMS_VISITS v',
'    JOIN   HMS_DOCTORS d ON d.DOCTOR_ID = v.DOCTOR_ID',
'    WHERE  v.VISIT_ID = :P7_VISIT_ID;',
'',
'    INSERT INTO HMS_INVOICES (VISIT_ID, PATIENT_ID, INVOICE_DATE)',
'    VALUES (:P7_VISIT_ID, l_patient, TRUNC(SYSDATE))',
'    RETURNING INVOICE_ID, INVOICE_NO INTO l_inv_id, l_inv_no;',
'',
'    INSERT INTO HMS_INVOICE_ITEMS (INVOICE_ID, DESCRIPTION, QTY, UNIT_PRICE)',
'    VALUES (l_inv_id, ''Consultation Fee'', 1, NVL(l_fee, 0));',
'',
'    INSERT INTO HMS_INVOICE_ITEMS (INVOICE_ID, DESCRIPTION, QTY, UNIT_PRICE)',
'    SELECT l_inv_id,',
'           m.MEDICINE_NAME || '' '' || m.STRENGTH,',
'           r.QUANTITY,',
'           m.UNIT_PRICE',
'    FROM   HMS_PRESCRIPTIONS r',
'    JOIN   HMS_MEDICINES m ON m.MEDICINE_ID = r.MEDICINE_ID',
'    WHERE  r.VISIT_ID = :P7_VISIT_ID;',
'',
'    apex_application.g_print_success_message :=',
'        ''Invoice '' || l_inv_no || '' ban gaya. Billing page par dekhein.'';',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(3493757645365774914)
,p_internal_uid=>3493757795065774915
,p_created_on=>wwv_flow_imp.dz('20261015071938Z')
,p_updated_on=>wwv_flow_imp.dz('20261015071938Z')
,p_created_by=>'MUHAMMADHAMMADMATLOOB@GMAIL.COM'
,p_updated_by=>'MUHAMMADHAMMADMATLOOB@GMAIL.COM'
);
