wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3485899869164579100)
,p_plug_name=>'Billing'
,p_static_id=>'billing'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2103954283454391425
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT i.INVOICE_ID,',
'       i.INVOICE_NO,',
'       p.MR_NO,',
'       p.FULL_NAME AS PATIENT_NAME,',
'       i.INVOICE_DATE,',
'       i.TOTAL_AMOUNT,',
'       i.DISCOUNT,',
'       (i.TOTAL_AMOUNT - i.DISCOUNT) AS NET_AMOUNT,',
'       i.PAID_AMOUNT,',
'       (i.TOTAL_AMOUNT - i.DISCOUNT - i.PAID_AMOUNT) AS BALANCE,',
'       CASE i.STATUS',
'         WHEN ''Paid''    THEN ''<span class="badge-paid">Paid</span>''',
'         WHEN ''Partial'' THEN ''<span class="badge-partial">Partial</span>''',
'         ELSE                ''<span class="badge-unpaid">Unpaid</span>''',
'       END AS STATUS_BADGE,',
'       ''Print'' AS PRINT_LINK',
'FROM   HMS_INVOICES i',
'JOIN   HMS_PATIENTS p ON p.PATIENT_ID = i.PATIENT_ID',
'ORDER  BY i.INVOICE_DATE DESC, i.INVOICE_ID DESC'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
