,p_plug_name=>'Pharmacy'
,p_static_id=>'pharmacy'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2103954283454391425
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT r.RX_ID,',
'       p.MR_NO,',
'       p.FULL_NAME AS PATIENT_NAME,',
'       m.MEDICINE_NAME || '' '' || m.STRENGTH AS MEDICINE,',
'       r.DOSAGE,',
'       r.QUANTITY,',
'       m.STOCK_QTY,',
'       v.VISIT_DATE,',
'       CASE r.ISSUED',
'         WHEN ''Y'' THEN ''<span class="badge-paid">Issued</span>''',
'         ELSE ''<span class="badge-partial">Pending</span>''',
'       END AS STATUS_BADGE,',
'       CASE WHEN r.ISSUED = ''N'' THEN ''Issue'' END AS ISSUE_LINK',
'FROM   HMS_PRESCRIPTIONS r',
'JOIN   HMS_VISITS    v ON v.VISIT_ID    = r.VISIT_ID',
'JOIN   HMS_PATIENTS  p ON p.PATIENT_ID  = v.PATIENT_ID',
'JOIN   HMS_MEDICINES m ON m.MEDICINE_ID = r.MEDICINE_ID',
'ORDER  BY r.ISSUED, v.VISIT_DATE DESC, r.RX_ID DESC'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
