wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(3493759177050774929)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Issue Medicine'
,p_static_id=>'issue-medicine'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_qty    NUMBER;',
'    l_stock  NUMBER;',
'    l_issued CHAR(1);',
'    l_med    NUMBER;',
'BEGIN',
'    SELECT r.QUANTITY, m.STOCK_QTY, r.ISSUED, r.MEDICINE_ID',
'    INTO   l_qty, l_stock, l_issued, l_med',
'    FROM   HMS_PRESCRIPTIONS r',
'    JOIN   HMS_MEDICINES m ON m.MEDICINE_ID = r.MEDICINE_ID',
'    WHERE  r.RX_ID = :P14_RX_ID;',
'',
'    IF l_issued = ''Y'' THEN',
'        apex_error.add_error(',
'            p_message          => ''Yeh dawai pehle hi issue ho chuki hai.'',',
'            p_display_location => apex_error.c_inline_in_notification);',
'        RETURN;',
'    END IF;',
'',
'    IF l_stock < l_qty THEN',
'        apex_error.add_error(',
'            p_message          => ''Stock kam hai. Maujooda stock: '' || l_stock,',
'            p_display_location => apex_error.c_inline_in_notification);',
'        RETURN;',
'    END IF;',
'',
'    UPDATE HMS_MEDICINES SET STOCK_QTY = STOCK_QTY - l_qty',
'    WHERE  MEDICINE_ID = l_med;',
'',
'    UPDATE HMS_PRESCRIPTIONS SET ISSUED = ''Y'', ISSUED_AT = SYSTIMESTAMP',
'    WHERE  RX_ID = :P14_RX_ID;',
'',
'    apex_application.g_print_success_message := ''Dawai issue ho gayi, stock update ho gaya.'';',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'ISSUE'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_internal_uid=>3493759177050774929
,p_created_on=>wwv_flow_imp.dz('20261015090448Z')
,p_updated_on=>wwv_flow_imp.dz('20261015090448Z')
,p_created_by=>'MUHAMMADHAMMADMATLOOB@GMAIL.COM'
,p_updated_by=>'MUHAMMADHAMMADMATLOOB@GMAIL.COM'
);
end;
