wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1510853957270963953)
,p_plug_name=>'Appointments'
,p_static_id=>'appointments'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2103954283454391425
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT a.APPOINTMENT_ID,',
'       p.MR_NO,',
'       p.FULL_NAME     AS PATIENT_NAME,',
'       d.DOCTOR_NAME,',
'       dp.DEPT_NAME,',
'       a.APPOINTMENT_DATE,',
'       a.APPOINTMENT_TIME,',
'       CASE a.STATUS',
'         WHEN ''Scheduled'' THEN ''<span class="badge-scheduled">Scheduled</span>''',
'         WHEN ''Completed'' THEN ''<span class="badge-completed">Completed</span>''',
'         WHEN ''Cancelled'' THEN ''<span class="badge-cancelled">Cancelled</span>''',
'         ELSE ''<span class="badge-noshow">No Show</span>''',
'       END AS STATUS_BADGE,',
'       a.REASON,',
'              a.PATIENT_ID,',
'       a.DOCTOR_ID,',
'       ''Start Visit'' AS START_VISIT',
'FROM   HMS_APPOINTMENTS a',
'JOIN   HMS_PATIENTS    p  ON p.PATIENT_ID = a.PATIENT_ID',
'JOIN   HMS_DOCTORS     d  ON d.DOCTOR_ID  = a.DOCTOR_ID',
'JOIN   HMS_DEPARTMENTS dp ON dp.DEPT_ID   = d.DEPT_ID',
'WHERE  a.DOCTOR_ID IN (SELECT doctor_id FROM hms_visible_doctors)',
'ORDER  BY a.APPOINTMENT_DATE DESC, a.APPOINTMENT_TIME'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
